69	/// Cut `content` to at most `max_chars` Unicode scalar values.
70	///
71	/// Text that fits is returned unchanged. A longer text keeps its first `max_chars - 1` chars and ends in `…`, so the
72	/// result is exactly `max_chars` chars; a cap of 1 gives `…` and a cap of 0 gives the empty string. How much was cut
73	/// is in [`Truncated::removed`] and [`Truncated::hint`], never in `content`.
74	///
75	/// Uses char boundaries: never splits a Unicode scalar, though it can split a multi-part emoji or flag pair, which
76	/// stays valid UTF-8.
77	#[must_use]
78	pub fn truncate(content: &str, max_chars: usize) -> Truncated {
79	    let chars = content.chars().count();
80	    if chars <= max_chars {
81	        return Truncated { content: content.to_string(), original_chars: chars, removed: 0 };
82	    }
83	
84	    let kept = max_chars.saturating_sub(1);
85	    let byte_end = content.char_indices().nth(kept).map_or(content.len(), |(i, _)| i);
86	    let mut out = String::with_capacity(byte_end + ELLIPSIS.len_utf8());
87	    out.push_str(&content[..byte_end]);
88	    if max_chars > 0 {
89	        out.push(ELLIPSIS);
90	    }
91	    Truncated { content: out, original_chars: chars, removed: chars - kept }
92	}
